// Explicit Arduino teaching subset. No eval or execution of arbitrary JavaScript.
export function compile(source){
 source=source.replace(/^\s*#([^\n]*)/gm,(full,directive)=>{if(!/^include\s*<(Wire|Adafruit_GFX|Adafruit_SSD1306)\.h>\s*$/.test(directive))throw Error('初版不支持预处理指令：#'+directive);return full;});
 const tokens=[];let line=1,i=0;
 while(i<source.length){let s=source.slice(i),m;if((m=/^\s+/.exec(s))){line+=(m[0].match(/\n/g)||[]).length;i+=m[0].length;continue;}if(s.startsWith('//')||s[0]==='#'){let n=s.indexOf('\n');i+=n<0?s.length:n;continue;}if(s.startsWith('/*')){let n=s.indexOf('*/');if(n<0)throw Error(`第 ${line} 行：注释未结束`);line+=(s.slice(0,n+2).match(/\n/g)||[]).length;i+=n+2;continue;}
 if((m=/^(?:"(?:\\.|[^"\\])*"|0x[\da-f]+|\d+(?:\.\d+)?|[A-Za-z_]\w*|==|!=|<=|>=|&&|\|\||\+\+|--|\+=|-=|[{}()[\];,.+*/%<>=!&|?:-])/i.exec(s))){tokens.push({v:m[0],line});i+=m[0].length;}else throw Error(`第 ${line} 行：不支持的字符 ${s[0]}`);
 }tokens.push({v:'EOF',line});let p=0;const peek=()=>tokens[p].v,take=()=>tokens[p++],fail=m=>{throw Error(`第 ${tokens[p].line} 行：${m}`)},need=v=>{if(peek()!==v)fail(`需要 ${v}，这里是 ${peek()}`);return take();};
 const types=new Set(['int','float','double','bool','long','unsigned','uint8_t','uint16_t','int16_t','int32_t','uint32_t','String','const','static']);
 const prec={'=':1,'+=':1,'-=':1,'||':2,'&&':3,'==':4,'!=':4,'<':5,'>':5,'<=':5,'>=':5,'+':6,'-':6,'*':7,'/':7,'%':7};
 function expr(min=0){let t=take(),a;if(['!','-','+','&'].includes(t.v)){a={k:'un',op:t.v,a:expr(8),line:t.line};}else if(t.v==='('){a=expr();need(')');}else if(/^\d/.test(t.v)){a={k:'lit',v:Number(t.v)};}else if(t.v[0]==='"'){a={k:'lit',v:JSON.parse(t.v)};}else if(/^[A-Za-z_]\w*$/.test(t.v)){let name=t.v;while(peek()==='.'){take();name+='.'+take().v;}a={k:'id',name,line:t.line};}else fail('表达式不完整');
 while(true){if(peek()==='('){take();let args=[];if(peek()!==')'){do{args.push(expr());if(peek()!==',')break;take();}while(true);}need(')');if(a.k!=='id')fail('不支持这个函数调用');a={k:'call',name:a.name,args,line:t.line};continue;}if(['++','--'].includes(peek())){a={k:'post',a,op:take().v,line:t.line};continue;}let op=peek(),pr=prec[op];if(!pr||pr<min)break;take();a={k:'bin',op,a,b:expr(pr+(pr===1?0:1)),line:t.line};}return a;}
 function decl(){while(types.has(peek()))take();let name=take().v;if(!/^[A-Za-z_]\w*$/.test(name))fail('变量名无效');let value={k:'lit',v:0};if(peek()==='='){take();value=expr();}return{k:'decl',name,value,line:tokens[p].line};}
 function statement(){let l=tokens[p].line;if(peek()==='{'){take();let body=[];while(peek()!=='}'){if(peek()==='EOF')fail('缺少右花括号 }');body.push(statement());}take();return{k:'block',body,line:l};}if(peek()===';'){take();return{k:'block',body:[],line:l};}if(peek()==='if'){take();need('(');let cond=expr();need(')');let yes=statement(),no=null;if(peek()==='else'){take();no=statement();}return{k:'if',cond,yes,no,line:l};}if(peek()==='while'){take();need('(');let cond=expr();need(')');return{k:'while',cond,body:statement(),line:l};}if(peek()==='for'){take();need('(');let init=types.has(peek())?decl():{k:'expr',value:expr()};need(';');let cond=expr();need(';');let next=expr();need(')');return{k:'for',init,cond,next,body:statement(),line:l};}if(peek()==='return'){take();let value=peek()===';'?{k:'lit',v:0}:expr();need(';');return{k:'return',value,line:l};}let a=types.has(peek())?decl():{k:'expr',value:expr(),line:l};need(';');return a;}
 let globals=[],functions={};while(peek()!=='EOF'){if(peek()==='Adafruit_SSD1306'){take();let name=take().v;need('(');let args=[];while(peek()!==')'){args.push(expr());if(peek()!==',')break;take();}need(')');need(';');if(name!=='display')fail('初版屏幕对象请命名为 display');globals.push({k:'display',args});}else if(peek()==='void'){take();let name=take().v;need('(');need(')');if(functions[name])fail('函数重复定义');functions[name]=statement();}else if(types.has(peek())){globals.push(decl());need(';');}else fail(`初版不支持 ${peek()}；请查看支持范围`);}
 if(!functions.setup||!functions.loop)fail('需要 void setup() 和 void loop()');
 const calls=new Set(['Wire.begin','display.begin','display.clearDisplay','display.display','display.drawPixel','display.drawLine','display.drawRect','display.fillRect','display.drawCircle','display.fillCircle','display.drawRoundRect','display.fillRoundRect','display.setCursor','display.setTextSize','display.setTextColor','display.print','display.println','display.invertDisplay','delay','millis','pinMode','digitalWrite','digitalRead','analogRead','tone','noTone','Serial.begin','Serial.print','Serial.println','min','max','abs','random','sin','cos','sqrt']);
 function validate(a){if(!a||typeof a!=='object')return;if(a.k==='call'&&!calls.has(a.name)&&!functions[a.name])throw Error(`第 ${a.line} 行：初版尚不支持 ${a.name}()`);for(const v of Object.values(a)){if(Array.isArray(v))v.forEach(validate);else if(v&&typeof v==='object')validate(v);}}
 globals.forEach(validate);Object.values(functions).forEach(validate);
 const arity={'delay':[1],'millis':[0],'min':[2],'max':[2],'abs':[1],'sin':[1],'cos':[1],'sqrt':[1],'random':[1,2],'Wire.begin':[2],'display.begin':[2],'display.clearDisplay':[0],'display.display':[0],'display.drawPixel':[3],'display.drawLine':[5],'display.drawRect':[5],'display.fillRect':[5],'display.drawCircle':[4],'display.fillCircle':[4],'display.drawRoundRect':[6],'display.fillRoundRect':[6],'display.setCursor':[2],'display.setTextSize':[1],'display.setTextColor':[1],'display.print':[1],'display.println':[0,1],'display.invertDisplay':[1],'pinMode':[2],'digitalWrite':[2],'digitalRead':[1],'analogRead':[1],'tone':[2],'noTone':[0,1],'Serial.begin':[1],'Serial.print':[1],'Serial.println':[0,1]};
 function checkArgs(a){if(!a||typeof a!=='object')return;if(a.k==='call'&&!(arity[a.name]??[0]).includes(a.args.length))throw Error(`第 ${a.line} 行：${a.name}() 参数个数不正确或初版不支持此形式`);for(const v of Object.values(a))if(v&&typeof v==='object')Array.isArray(v)?v.forEach(checkArgs):checkArgs(v);}
 globals.forEach(checkArgs);Object.values(functions).forEach(checkArgs);return{globals,functions};
}
export async function execute(program,host,signal){
 const env={HIGH:1,LOW:0,OUTPUT:1,INPUT:0,INPUT_PULLUP:2,SSD1306_WHITE:1,SSD1306_BLACK:0,SSD1306_INVERSE:2,SSD1306_SWITCHCAPVCC:2,true:1,false:0,Wire:0,PI:Math.PI};let count=0,depth=0;const started=Date.now();
 async function tick(){if(signal.aborted)throw Error('STOPPED');if(++count%500===0)await new Promise(r=>setTimeout(r,0));if(count>200000)throw Error('程序运行步数过多。请在循环中加入 delay()。');}
 async function val(a){await tick();switch(a.k){case'lit':return a.v;case'id':if(!(a.name in env))throw Error(`第 ${a.line} 行：变量 ${a.name} 没有定义`);return env[a.name];case'un':{let v=await val(a.a);return a.op==='!'?!v:a.op==='-'?-v:v;}case'post':{if(a.a.k!=='id'||!(a.a.name in env))throw Error('自增需要已定义变量');let old=env[a.a.name];env[a.a.name]+=a.op==='++'?1:-1;return old;}case'bin':{let op=a.op;if(['=','+=','-='].includes(op)){if(a.a.k!=='id'||!(a.a.name in env))throw Error(`第 ${a.line} 行：赋值目标没有定义`);let b=await val(a.b);return env[a.a.name]=op==='='?b:op==='+='?env[a.a.name]+b:env[a.a.name]-b;}let x=await val(a.a);if(op==='&&')return x&&await val(a.b);if(op==='||')return x||await val(a.b);let y=await val(a.b);switch(op){case'+':return x+y;case'-':return x-y;case'*':return x*y;case'/':if(y===0)throw Error('不能除以零');return Number.isInteger(x)&&Number.isInteger(y)?Math.trunc(x/y):x/y;case'%':return Number.isInteger(x)&&Number.isInteger(y)?Math.trunc(x)%Math.trunc(y):x%y;case'==':return x===y;case'!=':return x!==y;case'<':return x<y;case'>':return x>y;case'<=':return x<=y;case'>=':return x>=y;}break;}case'call':{let args=[];for(const b of a.args)args.push(await val(b));if(program.functions[a.name]){if(++depth>20)throw Error('函数调用太深');let r=await stmt(program.functions[a.name]);depth--;return r?.value??0;}if(a.name==='delay'){let ms=args[0];if(!Number.isFinite(ms)||ms<0||ms>60000)throw Error('delay 范围为 0–60000 毫秒');count=0;for(let n=0;n<Math.max(ms,1);n+=20){if(signal.aborted)throw Error('STOPPED');await new Promise(r=>setTimeout(r,Math.min(20,Math.max(ms,1)-n)));}return 0;}if(a.name==='millis')return Date.now()-started;if(['sin','cos','sqrt','abs','min','max'].includes(a.name))return Math[a.name](...args);if(a.name==='random')return args.length===1?Math.floor(Math.random()*args[0]):Math.floor(args[0]+Math.random()*(args[1]-args[0]));return host.call(a.name,args);}}
 }
 async function stmt(s){await tick();if(s.k==='block'){for(const b of s.body){let r=await stmt(b);if(r)return r;}}else if(s.k==='decl'){env[s.name]=await val(s.value);}else if(s.k==='expr'){await val(s.value);}else if(s.k==='return')return{value:await val(s.value)};else if(s.k==='if'){if(await val(s.cond))return stmt(s.yes);else if(s.no)return stmt(s.no);}else if(s.k==='while'){while(await val(s.cond)){let r=await stmt(s.body);if(r)return r;}}else if(s.k==='for'){await stmt(s.init);while(await val(s.cond)){let r=await stmt(s.body);if(r)return r;await val(s.next);}}}
 for(const g of program.globals){if(g.k==='display'){const dims=[];for(const a of g.args)dims.push(await val(a));if(dims[0]!==128||dims[1]!==64)throw Error('初版支持 128 × 64 OLED');}else await stmt(g);}await stmt(program.functions.setup);while(!signal.aborted){await stmt(program.functions.loop);await new Promise(r=>setTimeout(r,16));}
}
